function tarjanScc(edges){
  var adj={}, nodes=[], seen={};
  function addNode(v){ if(!seen[v]){ seen[v]=1; nodes.push(v); adj[v]=adj[v]||[]; } }
  for(var i=0;i<edges.length;i++){
    var e=edges[i];
    addNode(e[0]); addNode(e[1]);
    adj[e[0]].push(e[1]);
  }
  var index={}, low={}, onStack={}, stack=[], counter={n:0}, sccs=[];
  function strongconnect(v){
    index[v]=counter.n; low[v]=counter.n; counter.n++;
    stack.push(v); onStack[v]=true;
    var nbrs=adj[v]||[];
    for(var j=0;j<nbrs.length;j++){
      var w=nbrs[j];
      if(index[w]===undefined){
        strongconnect(w);
        if(low[w]<low[v]) low[v]=low[w];
      } else if(onStack[w]){
        if(index[w]<low[v]) low[v]=index[w];
      }
    }
    if(low[v]===index[v]){
      var comp=[], u;
      do { u=stack.pop(); onStack[u]=false; comp.push(u); } while(u!==v);
      comp.sort();
      sccs.push(comp);
    }
  }
  for(var k=0;k<nodes.length;k++){
    if(index[nodes[k]]===undefined) strongconnect(nodes[k]);
  }
  return sccs;
}
function sccCondense(edges){
  var sccs=tarjanScc(edges);
  var compOf={};
  for(var i=0;i<sccs.length;i++){
    for(var j=0;j<sccs[i].length;j++) compOf[sccs[i][j]]=i;
  }
  var dedup={}, dagEdges=[];
  for(var k=0;k<edges.length;k++){
    var a=compOf[edges[k][0]], b=compOf[edges[k][1]];
    if(a!==b){
      var key=a+'->'+b;
      if(!dedup[key]){ dedup[key]=1; dagEdges.push([a,b]); }
    }
  }
  return { sccs:sccs, compOf:compOf, dagEdges:dagEdges };
}
function sccHasCycle(edges){
  var sccs=tarjanScc(edges);
  for(var i=0;i<sccs.length;i++) if(sccs[i].length>1) return true;
  var self={};
  for(var k=0;k<edges.length;k++) if(edges[k][0]===edges[k][1]) return true;
  return false;
}
function parseEdges(text){
  var out=[];
  var lines=String(text).split('\n');
  for(var i=0;i<lines.length;i++){
    var ln=lines[i].trim();
    if(!ln) continue;
    var mm=ln.split('->');
    if(mm.length!==2) return {value:null, error:'第 '+(i+1)+' 行格式错误（需 a->b）'};
    var a=mm[0].trim(), b=mm[1].trim();
    if(!a||!b) return {value:null, error:'第 '+(i+1)+' 行节点为空'};
    out.push([a,b]);
  }
  return {value:out, error:null};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tarjanScc:tarjanScc, sccCondense:sccCondense, sccHasCycle:sccHasCycle, parseEdges:parseEdges };
}
if (typeof window !== 'undefined') {
  window.TarjanForgePure = { tarjanScc:tarjanScc, sccCondense:sccCondense, sccHasCycle:sccHasCycle, parseEdges:parseEdges };
}
